import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"写作课作业-014","description":"","frontmatter":{"date":"2020-08-11T20:09:24","title":"写作课作业-014","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/014.md","filePath":"posts/homework/014.md"}'),p={name:"posts/homework/014.md"};function s(i,e,n,_,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<blockquote><p>我们都听过0.618法则，这个法则一般用在什么地方？还可以用在什么地方？传达一个概念要多个角度思考的重要性的感知。</p></blockquote><p>二八法则大家可能耳熟能详，0.618黄金分割点或许也不陌生，常在数学和美学中被提及，但0.618和法则结合，可能就要打问号了。维基百科上是这么介绍的，0.618法，又叫黄金分割法，是<a href="https://zh.wikipedia.org/w/index.php?title=%E4%BC%98%E9%80%89%E6%B3%95&amp;action=edit&amp;redlink=1" target="_blank" rel="noreferrer">优选法</a>的一种。它在试验时，把试点安排在<a href="https://zh.wikipedia.org/wiki/%E9%BB%84%E9%87%91%E5%88%86%E5%89%B2" target="_blank" rel="noreferrer">黄金分割</a>点上来寻找最佳点。而生产生活中，我们常常取其近似值0.618，因此得名。0.618法是最常用的单因素单峰目标函数优选法之一。</p><p>李永乐老师讲了一期《<a href="https://www.youtube.com/watch?v=pelPCK22W7k" target="_blank" rel="noreferrer">什么是爱情？怎么谈恋爱，才能有效的找到自己的真命天子？李永乐老师讲爱情数学</a>》，提到1/e约为0.368，如何有100个候选人，选第37位可能选中真命天子的概率比较大。类似的，0.618法也可以用于有限条件下的决策。比如只把笔试成绩排名前37%的人叫来面试，节省公司资源。比如把产品价格按市场最高，最低的黄金分割点，保证收益。</p><p>那0.618法与二八法则怎么选呢，我的理解是：</p><p>0.2*0.8=0.16</p><p>0.4*0.6=0.24</p><p>在有限成本的前提下，二八法能快速出效益，0.618法则更平衡和效益更大化。</p>',7)])])}const k=t(p,[["render",s]]);export{h as __pageData,k as default};
